/**
 * Industry hero art — one DISTINCT image per industry slug.
 *
 * HISTORY: this map previously pointed nine different industries at the same
 * "business" stock photo (retail duplicated eCommerce, schools duplicated
 * education, clinics duplicated healthcare), so every industry page looked
 * identical. Each entry below is now its own committed file under
 * `public/images/industries/`, generated by
 * `scripts/generate-industry-heroes.mjs` in the site's own diagram language:
 * no stock licence, no real person, no real brand, English-only labels.
 *
 * These are ILLUSTRATIVE architecture diagrams, never photographs of customers,
 * institutions or measured systems. Alt text says so on every surface.
 */
export const INDUSTRY_IMAGES: Record<string, string> = {
  ecommerce: '/images/industries/ecommerce-hero.png',
  education: '/images/industries/education-hero.png',
  'schools-training': '/images/industries/schools-training-hero.png',
  healthcare: '/images/industries/healthcare-hero.png',
  'hospitals-clinics': '/images/industries/hospitals-clinics-hero.png',
  'real-estate': '/images/industries/real-estate-hero.png',
  'restaurants-food': '/images/industries/restaurants-food-hero.png',
  agencies: '/images/industries/agencies-hero.png',
  'professional-services': '/images/industries/professional-services-hero.png',
  'marketing-agencies': '/images/industries/marketing-agencies-hero.png',
  'local-businesses': '/images/industries/local-businesses-hero.png',
  'international-smes': '/images/industries/international-smes-hero.png',
  finance: '/images/industries/finance-hero.png',
  retail: '/images/industries/retail-hero.png',
  logistics: '/images/industries/logistics-hero.png',
  'travel-hospitality': '/images/industries/travel-hospitality-hero.png',
  construction: '/images/industries/construction-hero.png',
  manufacturing: '/images/industries/manufacturing-hero.png',
  'legal-services': '/images/industries/legal-services-hero.png',
  'technology-companies': '/images/industries/technology-companies-hero.png',
};

export function industryImage(slug: string): string | undefined {
  return INDUSTRY_IMAGES[slug];
}

/** Accessible alt text for an industry hero image. */
export function industryImageAlt(name: string): string {
  return `${name} operating-system architecture diagram — illustrative, not a client system`;
}
